@Override
    public void tick() {
        super.tick();
        if (!this.isInWaterOrBubble() && !this.hasEffect(ACEffectRegistry.BUBBLED.get())) {
            this.addEffect(new MobEffectInstance(ACEffectRegistry.BUBBLED.get(), 200));
        }
        if (this.isInWaterOrBubble() && this.hasEffect(ACEffectRegistry.BUBBLED.get())) {
            this.removeEffect(ACEffectRegistry.BUBBLED.get());
        }
        isMageInWater = this.isInWaterOrBubble();
        if (this.getAnimation() == ANIMATION_SPIN) {
            this.setDeltaMovement(this.getDeltaMovement().scale(0.6F));
            LivingEntity target = this.getTarget();
            if (target != null) {
                Vec3 vec = target.position().subtract(this.position()).normalize();
                this.setDeltaMovement(this.getDeltaMovement().add(vec.scale(0.1)));
            }
            if (this.getAnimationTick() % 6 == 0) {
                AABB bashBox = this.getBoundingBox().inflate(2.0D, 0, 2.0D);
                for (LivingEntity entity : DeepOneMageEntity.this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
                    if (!isAlliedTo(entity) && !(entity instanceof DeepOneBaseEntity)) {
                        checkAndDealMeleeDamage(entity, 0.4F, 1.0F);
                    }
                }

            }
        }
        if (this.getAnimation() == ANIMATION_ATTACK) {
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                if (this.getAnimationTick() == 16) {
                    useMagicAttack(target);
                } else if (this.getAnimationTick() < 16) {
                    this.level().broadcastEntityEvent(this, (byte) 68);
                }
                this.getLookControl().setLookAt(target.getX(), target.getEyeY(), target.getZ(), 180.0F, 10.0F);
            }
        }
        if (spinCooldown > 0) {
            spinCooldown--;
        }
        if (rangedCooldown > 0) {
            rangedCooldown--;
        }
    }

@Override
    public void startAttackBehavior(LivingEntity target) {
        this.yBodyRot = this.getYRot();
        double distance = this.distanceTo(target);
        float f = this.getBbWidth() + target.getBbWidth();
        if (distance > 20 + f) {
            this.getNavigation().moveTo(target, 1.2);
        } else if (distance < 2F + f && spinCooldown <= 0) {
            if (this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(ANIMATION_SPIN);
                spinCooldown = 1000 + random.nextInt(60);
            }
        } else {
            if (strafeTarget == null || strafeTarget.distanceTo(this.position()) < 4) {
                Vec3 possible = target.position().add(random.nextInt(20) - 10, random.nextInt(2), random.nextInt(20) - 10);
                if (!isTargetBlocked(possible)) {
                    strafeTarget = possible;
                }
            } else {
                this.getNavigation().moveTo(strafeTarget.x, strafeTarget.y, strafeTarget.z, 1.5F);
            }
            if (rangedCooldown <= 0 && this.getAnimation() == NO_ANIMATION && hasLineOfSight(target)) {
                this.setAnimation(ANIMATION_ATTACK);
                this.playSound(ACSoundRegistry.DEEP_ONE_MAGE_ATTACK.get());
                rangedCooldown = 30 + random.nextInt(20);
            }
            this.getLookControl().setLookAt(target.getX(), target.getEyeY(), target.getZ(), 30.0F, 10.0F);

        }
    }

public void useMagicAttack(LivingEntity target) {
        this.level().broadcastEntityEvent(this, (byte) 68);
        if (random.nextBoolean()) {
            int lifespan = (int) (Math.floor(this.distanceTo(target))) + 10;
            Vec3 vec3 = target.position().subtract(this.position());
            for (int i = -2; i <= 2; i++) {
                WaveEntity waveEntity = new WaveEntity(this.level(), this);
                waveEntity.setPos(this.getX(), target.getY(), this.getZ());
                waveEntity.setLifespan(lifespan);
                waveEntity.setYRot(-(float) (Mth.atan2(vec3.x, vec3.z) * (double) (180F / (float) Math.PI)) + (i * 10));
                this.level().addFreshEntity(waveEntity);
            }
        } else {
            WaterBoltEntity waterBoltEntity = new WaterBoltEntity(this.level(), this);
            double d0 = target.getX() - this.getX();
            double d1 = target.getY(0.3333333333333333D) - waterBoltEntity.getY();
            double d2 = target.getZ() - this.getZ();
            double d3 = Math.sqrt(d0 * d0 + d2 * d2);
            waterBoltEntity.setBubbling(random.nextInt(2) == 0);
            waterBoltEntity.setArcingTowards(target.getUUID());
            waterBoltEntity.shoot(d0, d1 + d3 * (double) 0.67F, d2, 0.6F, 30);
            this.level().addFreshEntity(waterBoltEntity);

        }
    }

public void handleEntityEvent(byte b) {
        if (b == 66) {
            for (int i = 0; i < 2 + random.nextInt(4); i++) {
                this.level().addParticle(random.nextBoolean() ? ACParticleRegistry.DEEP_ONE_MAGIC.get() : ParticleTypes.DOLPHIN, this.getRandomX(1F), this.getRandomY(), this.getRandomZ(1F), 0F, -0.1F, 0F);
            }
        } else if (b == 67) {
            for (int i = 0; i < 13 + random.nextInt(6); i++) {
                this.level().addParticle(ACParticleRegistry.DEEP_ONE_MAGIC.get(), this.getRandomX(1F), this.getRandomY(), this.getRandomZ(1F), random.nextFloat() - 0.5F, random.nextFloat() - 0.5F, random.nextFloat() - 0.5F);
                this.level().addParticle(ParticleTypes.NAUTILUS, this.getRandomX(1F), this.getRandomY() + 1, this.getRandomZ(1F), random.nextFloat() - 0.5F, random.nextFloat() - 0.5F, random.nextFloat() - 0.5F);
            }
        } else if (b == 68) {
            Vec3 deltaPos = this.position().add(getDeltaMovement());
            Vec3 rVec = new Vec3(0.65F, this.getBbHeight() * 0.5F + 0.15F, 0.2F).xRot(-this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYHeadRot() * ((float) Math.PI / 180F)).add(deltaPos);
            Vec3 lVec = new Vec3(-0.65F, this.getBbHeight() * 0.5F + 0.15F, 0.2F).xRot(-this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYHeadRot() * ((float) Math.PI / 180F)).add(deltaPos);
            this.level().addParticle(ACParticleRegistry.DEEP_ONE_MAGIC.get(), rVec.x + (random.nextFloat() - 0.5F) * 0.1F, rVec.y + (random.nextFloat() - 0.5F) * 0.1F, rVec.z + (random.nextFloat() - 0.5F) * 0.1F, (random.nextFloat() - 0.5F) * 0.3F + getDeltaMovement().x, 1, (random.nextFloat() - 0.5F) * 0.3F + getDeltaMovement().z);
            this.level().addParticle(ACParticleRegistry.DEEP_ONE_MAGIC.get(), lVec.x + (random.nextFloat() - 0.5F) * 0.1F, lVec.y + (random.nextFloat() - 0.5F) * 0.1F, lVec.z + (random.nextFloat() - 0.5F) * 0.1F, (random.nextFloat() - 0.5F) * 0.3F + getDeltaMovement().x, 1, (random.nextFloat() - 0.5F) * 0.3F + getDeltaMovement().z);

        } else {
            super.handleEntityEvent(b);
        }
    }

@Override
    public boolean canUse() {
        return deepOne.getTarget() != null && deepOne.getTarget().isAlive() && !deepOne.isTradingLocked();
    }

@Override
    public void stop(){
        super.stop();
        deepOne.setSoundsAngry(false);
    }

public void tick() {
        LivingEntity target = deepOne.getTarget();
        if (target != null) {
            deepOne.getLookControl().setLookAt(target.getX(), target.getEyeY(), target.getZ(), 20.0F, (float) deepOne.getMaxHeadXRot());
            deepOne.startAttackBehavior(target);
            deepOne.setSoundsAngry(true);
            if(deepOne.distanceTo(target) <= 16){
                SubmarineEntity.alertSubmarineMountOf(target);
            }
        }
    }

public void tick() {
        super.tick();
        prevSlamProgress = slamProgress;
        if(this.getWaitingTicks() > 0){
            if(!level().isClientSide){
                this.setWaitingTicks(this.getWaitingTicks() - 1);
            }
            this.setInvisible(true);
            return;
        }else{
            if(this.isInvisible()){
                this.setInvisible(false);
            }
        }
        if (isSlamming() && slamProgress < 10.0F) {
            slamProgress += 1F;
        }
        if (isSlamming() && slamProgress == 10.0F) {
            this.discard();
        }
        if (!this.isNoGravity() && !this.isInWaterOrBubble()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, (double) -0.04F, 0.0D));
        }
        float f = Math.min(this.activeWaveTicks / 10F, 1F);
        Vec3 directionVec = new Vec3(0, 0, f * f * 0.2F).yRot((float) Math.toRadians(-this.getYRot()));
        if (this.level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
            for(int particleCount = 0; particleCount < getWaveScale(); particleCount++){
                for (int i = 0; i <= 4; i++) {
                    float xOffset = (float) i / 4F - 0.5F + (random.nextFloat() - 0.5F) * 0.2F;
                    spawnParticleAt((0.2F + random.nextFloat() * 0.2F) * this.getWaveScale(), 1.2F, xOffset * 1.2F * this.getWaveScale(), ACParticleRegistry.WATER_FOAM.get());
                    spawnParticleAt((0.2F + random.nextFloat() * 0.2F) * this.getWaveScale(), -0.2F, xOffset * 1.4F * this.getWaveScale(), ParticleTypes.SPLASH);
                }
            }
        } else {
            this.reapplyPosition();
            this.setRot(this.getYRot(), this.getXRot());
        }
        if (!level().isClientSide) {
            attackEntities(getSlamAmount(1.0F) * 2 + 1 + this.getWaveScale());
        }
        Vec3 vec3 = this.getDeltaMovement().scale(0.9F).add(directionVec);
        this.move(MoverType.SELF, vec3);
        this.setDeltaMovement(vec3.multiply((double) 0.99F, (double) 0.98F, (double) 0.99F));
        if (this.activeWaveTicks > getLifespan() || this.activeWaveTicks > 10 && this.getDeltaMovement().horizontalDistance() < 0.04) {
            this.setSlamming(true);
        }
        activeWaveTicks++;
    }

private void attackEntities(float scale) {
        AABB bashBox = this.getBoundingBox().inflate(0.5f, 0.5f, 0.5f);
        DamageSource source = damageSources().mobProjectile(this, owner);
        for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
            if (!isAlliedTo(entity) && !(entity instanceof DeepOneBaseEntity) && (owner == null || !owner.equals(entity) && !owner.isAlliedTo(entity))) {
                entity.hurt(source, scale + 1.0F);
                this.setSlamming(true);
                entity.knockback(0.1D + 0.5D * scale, (double) Mth.sin(this.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(this.getYRot() * ((float) Math.PI / 180F))));
            }
        }
    }

@Nullable
    public LivingEntity getOwner() {
        if (this.owner == null && this.ownerUUID != null && this.level() instanceof ServerLevel) {
            Entity entity = ((ServerLevel) this.level()).getEntity(this.ownerUUID);
            if (entity instanceof LivingEntity) {
                this.owner = (LivingEntity) entity;
            }
        }

        return this.owner;
    }

protected void addAdditionalSaveData(CompoundTag compoundTag) {
        if (this.ownerUUID != null) {
            compoundTag.putUUID("Owner", this.ownerUUID);
        }
        compoundTag.putInt("Lifespan", this.getLifespan());
    }

protected void readAdditionalSaveData(CompoundTag tag) {
        if (tag.hasUUID("Owner")) {
            this.ownerUUID = tag.getUUID("Owner");
        }
        if (tag.contains("Lifespan")) {
            this.setLifespan(tag.getInt("Lifespan"));
        }
    }

public void tick() {
        super.tick();
        if (!level().isClientSide) {
            Entity arcTowards = getArcingTowards();
            if (arcTowards != null && (tickCount > 3 || seekAmount > 0.3) && dieIn == -1 && this.distanceTo(arcTowards) > 1.5F && (tickCount < 20 || seekAmount > 0.3 && tickCount < 40)) {
                Vec3 arcVec = arcTowards.position().add(0, 0.85F * arcTowards.getBbHeight(), 0).subtract(this.position()).normalize();
                float prevDeltaScale = 1.0F - (seekAmount - 0.3F) * 0.3F;
                this.setDeltaMovement(this.getDeltaMovement().scale(prevDeltaScale).add(arcVec.scale(seekAmount)));
            }
        } else {
            for (int j = 0; j < 3 + random.nextInt(2); ++j) {
                this.level().addParticle(this.isInWaterOrBubble() || isBubbling() ? ParticleTypes.BUBBLE_COLUMN_UP : ParticleTypes.FALLING_WATER, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), 0, -0.1F, 0);
            }
        }
        if(wooshSoundTime <= 0){
            wooshSoundTime = 30 + level().random.nextInt(30);
            this.playSound(ACSoundRegistry.SEA_STAFF_WOOSH.get());
        }
        Vec3 vec3 = this.getDeltaMovement();
        double d0 = this.getX() + vec3.x;
        double d1 = this.getY() + vec3.y;
        double d2 = this.getZ() + vec3.z;
        this.updateRotation();
        float f = 0.99F;
        float f1 = 0.06F;
        if (this.level().getBlockStates(this.getBoundingBox()).noneMatch(BlockBehaviour.BlockStateBase::isAir) && !this.isInWaterOrBubble()) {
            this.discard();
        } else {
            this.setDeltaMovement(vec3.scale((double) 0.9F));
            if (!this.isNoGravity()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, (double) -0.07F, 0.0D));
            }
            if (this.level().isClientSide) {
                if (this.lSteps > 0) {
                    double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                    double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                    double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                    this.setYRot(Mth.wrapDegrees((float) this.lyr));
                    this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                    --this.lSteps;
                    this.setPos(d5, d6, d7);
                } else {
                    this.reapplyPosition();
                }
            } else {
                this.setPos(d0, d1, d2);
            }
        }
        Vec3 trailAt = this.position().add(0, this.getBbHeight() / 2F, 0);
        if (trailPointer == -1) {
            Vec3 backAt = trailAt;
            for (int i = 0; i < trailPositions.length; i++) {
                trailPositions[i] = backAt;
            }
        }
        if (++this.trailPointer == this.trailPositions.length) {
            this.trailPointer = 0;
        }
        this.trailPositions[this.trailPointer] = trailAt;

        HitResult hitresult = ProjectileUtil.getHitResultOnMoveVector(this, this::canHitEntity);
        if (hitresult.getType() != HitResult.Type.MISS && !net.minecraftforge.event.ForgeEventFactory.onProjectileImpact(this, hitresult)) {
            this.onHit(hitresult);
        }
        if (dieIn > 0) {
            dieIn--;
            if (dieIn == 0) {
                this.discard();
            }
        }
    }

protected void onHitEntity(EntityHitResult hitResult) {
        super.onHitEntity(hitResult);
        if(!playedSplashSound){
            playedSplashSound = true;
            this.playSound(ACSoundRegistry.SEA_STAFF_HIT.get());
        }
        if (!this.level().isClientSide && !ownedBy(hitResult.getEntity()) && tickCount > 2) {
            damageMobs();
            if (dieIn == -1) {
                dieIn = 5;
            }
        }
    }

protected void onHitBlock(BlockHitResult hitResult) {
        super.onHitBlock(hitResult);
        if(!playedSplashSound){
            playedSplashSound = true;
            this.playSound(ACSoundRegistry.SEA_STAFF_HIT.get());
        }
        if (!this.level().isClientSide) {
            damageMobs();
            if (dieIn == -1) {
                dieIn = 5;
            }
        }
    }

private void damageMobs() {
        Entity owner = this.getOwner();
        DamageSource source = damageSources().mobProjectile(this, (owner instanceof LivingEntity living1 ? living1 : null));
        AABB bashBox = this.getBoundingBox().inflate(2.0D, 2, 2.0D);
        Entity lastHitMob = null;
        for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
            if (!isAlliedTo(entity) && !(entity instanceof DeepOneBaseEntity) && (owner == null || !entity.is(owner) && !entity.isAlliedTo(owner))) {
                lastHitMob = entity;
                if (entity.hurt(source, 3.0F) && this.isBubbling()) {
                    entity.addEffect(new MobEffectInstance(ACEffectRegistry.BUBBLED.get(), 200));
                    if (!entity.level().isClientSide) {
                        AlexsCaves.sendMSGToAll(new UpdateEffectVisualityEntityMessage(entity.getId(), this.getId(), 1, 200));
                    }
                }
            }
        }
        if(ricochet && lastHitMob != null){
            ricochet = false;
            onRicochetHit(lastHitMob);
        }
    }

private void onRicochetHit(Entity hitBy) {
        Entity owner = this.getOwner();
        AABB searchBox = hitBy.getBoundingBox().inflate(32.0D, 32.0D, 32.0D);
        Entity ricochetTo = null;
        for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, searchBox)) {
            if (!isAlliedTo(entity) && !(entity instanceof DeepOneBaseEntity) && !entity.is(hitBy) && (owner == null || !entity.is(owner) && !entity.isAlliedTo(owner)) && entity.distanceTo(hitBy) > 3.0D) {
                if(ricochetTo == null || ricochetTo.distanceTo(hitBy) > entity.distanceTo(hitBy)){
                    ricochetTo = entity;
                }
            }
        }
        if(ricochetTo != null && owner instanceof LivingEntity living){
            WaterBoltEntity bolt = new WaterBoltEntity(level(), living);
            bolt.copyPosition(this);
            bolt.setArcingTowards(ricochetTo.getUUID());
            Vec3 arcVec = ricochetTo.position().add(0, 0.3F + 1 * ricochetTo.getBbHeight(), 0).subtract(this.position()).normalize();
            bolt.setDeltaMovement(bolt.getDeltaMovement().add(arcVec));
            bolt.setBubbling(this.isBubbling());
            level().addFreshEntity(bolt);
        }
    }

public void remove(Entity.RemovalReason removalReason) {
        super.remove(removalReason);
        if (!spawnedSplash && level() instanceof ServerLevel serverLevel) {
            spawnedSplash = true;
            BlockPos pos = this.blockPosition().above();
            while (level().isEmptyBlock(pos) && pos.getY() > level().getMinBuildHeight()) {
                pos = pos.below();
            }
            serverLevel.sendParticles(ACParticleRegistry.BIG_SPLASH.get(), this.getX(), pos.getY() + 1.5F, this.getZ(), 0, 1.3F, 1, 0, 1.0D);
        }
    }

protected void addAdditionalSaveData(CompoundTag compoundTag) {
        compoundTag.putBoolean("Bubbling", this.isBubbling());
    }

protected void readAdditionalSaveData(CompoundTag tag) {
        this.setBubbling(tag.getBoolean("Bubbling"));

    }

@Override
    public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (!this.level().isClientSide) {
            if (this.getAnimation() == NO_ANIMATION && (this.getTarget() == null || !this.getTarget().isAlive())) {
                if (this.getDeltaMovement().lengthSqr() < 0.03D && (getRandom().nextInt(500) == 0 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK))) {
                    this.setAnimation(ANIMATION_EAT_GRASS);
                } else if (getRandom().nextInt(200) == 0) {
                    this.setAnimation(ANIMATION_FLICK_EARS);
                }
            }
            if (this.getAnimation() == ANIMATION_EAT_GRASS && this.getAnimationTick() == 30 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK)) {
                BlockPos down = this.blockPosition().below();
                this.level().levelEvent(2001, down, Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
                this.level().setBlock(down, Blocks.DIRT.defaultBlockState(), 2);
                this.heal(10);
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                this.setAngry(this.distanceTo(target) < 20);
                double dist = this.distanceTo(target);
                if (hasLineOfSight(target)) {
                    this.lookAt(target, 30, 30);
                    this.yBodyRot = this.getYRot();
                }
                if (dist < this.getBbWidth() + 3.0F) {
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(random.nextBoolean() ? ANIMATION_SLASH : ANIMATION_FLING);
                    }
                    if(dist < this.getBbWidth() + 1.5F && this.hasLineOfSight(target)){
                        if (this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 8) {
                            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                            if (target instanceof Raider) {
                                dmg = 10;
                            }
                            attackWithPotion(target, dmg);
                            launch(target, 0, 1F);
                            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                                if(!(entity instanceof Animal) && !trusts(entity.getUUID()) && entity != target){
                                    attackWithPotion(entity, Math.max(dmg - 5, 1));
                                    launch(entity, 0, 0.5F);
                                }
                            }
                        }
                        if (this.getAnimation() == ANIMATION_SLASH && (this.getAnimationTick() >= 9 && this.getAnimationTick() <= 11 || this.getAnimationTick() >= 19 && this.getAnimationTick() <= 21)) {
                            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                            if (target instanceof Raider) {
                                dmg = 10;
                            }
                            attackWithPotion(target, dmg);
                            launch(target, this.getAnimationTick() <= 15 ? -90 : 90, 1F);
                            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                                if(!(entity instanceof Animal) && !trusts(entity.getUUID()) && entity != target){
                                    attackWithPotion(entity, Math.max(dmg - 5, 1));
                                    launch(entity, this.getAnimationTick() <= 15 ? -90 : 90, 0.5F);
                                }
                            }
                        }
                    }
                }
            }else{
                this.setAngry(false);
            }
        }
    }

protected void registerGoals() {
        super.registerGoals();
        this.goalSelector.addGoal(0, new FloatGoal(this));
        this.goalSelector.addGoal(1, new MeleeAttackGoal(this, 1.4D, true));
        this.goalSelector.addGoal(2, new AnimalAIPanicBaby(this, 1.25D));
        this.goalSelector.addGoal(3, new BreedGoal(this, 1.0D));
        this.goalSelector.addGoal(4, new TemptGoal(this, 1.0D, Ingredient.fromValues(Stream.of(new Ingredient.TagValue(AMTagRegistry.RHINOCEROS_FOODSTUFFS), new Ingredient.TagValue(AMTagRegistry.RHINOCEROS_BREEDABLES))), false));
        this.goalSelector.addGoal(5, new FollowParentGoal(this, 1.1D));
        this.goalSelector.addGoal(6, new AnimalAIWanderRanged(this, 90, 1.0D, 18, 7));
        this.goalSelector.addGoal(7, new StrollGoal(200));
        this.goalSelector.addGoal(8, new LookAtPlayerGoal(this, Player.class, 15.0F));
        this.goalSelector.addGoal(8, new RandomLookAroundGoal(this));
        this.targetSelector.addGoal(1, new DefendTrustedTargetGoal(LivingEntity.class, false, false, (entity) -> {
            return !this.trusts(entity.getUUID());
        }));
        this.targetSelector.addGoal(2, new NearestAttackableTargetGoal<>(this, Raider.class, 50, true, true, null){
            public boolean canUse(){
                return super.canUse() && !EntityRhinoceros.this.isBaby();
            }
        });
        this.targetSelector.addGoal(3, (new EntityRhinoceros.AIAttackNearPlayers()));
        this.targetSelector.addGoal(4, (new AnimalAIHurtByTargetNotBaby(this)));
    }

public InteractionResult mobInteract(Player player, InteractionHand hand) {
        ItemStack itemstack = player.getItemInHand(hand);
        InteractionResult type = super.mobInteract(player, hand);
        if(!isBaby() && (itemstack.getItem() == Items.POTION || itemstack.getItem() == Items.SPLASH_POTION || itemstack.getItem() == Items.LINGERING_POTION)){
            Potion contained = PotionUtils.getPotion(itemstack);
            if(applyPotion(contained)){
                this.gameEvent(GameEvent.ENTITY_INTERACT);
                this.playSound(SoundEvents.DYE_USE);
                this.usePlayerItem(player, hand, itemstack);
                ItemStack bottle = new ItemStack(Items.GLASS_BOTTLE);
                if(!player.addItem(bottle)){
                    player.drop(bottle, false);
                }
                return InteractionResult.SUCCESS;
            }
        } else if (itemstack.is(AMTagRegistry.RHINOCEROS_FOODSTUFFS) && !trusts(player.getUUID())) {
            addTrustedUUID(player.getUUID());
            this.usePlayerItem(player, hand, itemstack);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.HORSE_EAT);
            return InteractionResult.SUCCESS;
        }
        return type;
    }

public boolean applyPotion(Potion potion){
        if(potion == null || potion == Potions.WATER){
            resetPotion();
            return true;
        }else{
            if(potion.getEffects().size() >= 1){
                MobEffectInstance first = potion.getEffects().get(0);
                ResourceLocation loc = ForgeRegistries.MOB_EFFECTS.getKey(first.getEffect());
                if(loc != null){
                    this.setAppliedPotionId(loc.toString());
                    this.setPotionLevel(first.getAmplifier());
                    this.setPotionDuration(first.getDuration());
                    this.setInflictedCount(0);
                    return true;
                }
            }
        }
        return false;
    }

private void attackWithPotion(LivingEntity target, float dmg) {
        MobEffect potion = this.getPotionEffect();

        target.hurt(this.damageSources().mobAttack(this), dmg);
        if(potion != null){
            MobEffectInstance instance = new MobEffectInstance(potion, this.getPotionDuration(), this.getPotionLevel());
            if (!target.hasEffect(potion) && target.addEffect(instance)) {
                this.setInflictedCount(this.getInflictedCount() + 1);
            }
        }
        if(this.getInflictedCount() > 15 && random.nextInt(3) == 0 || this.getInflictedCount() > 20){
            this.resetPotion();
        }
    }

public void resetPotion() {
        this.setAppliedPotionId("");
        this.setPotionDuration(0);
        this.setPotionLevel(0);
        this.setInflictedCount(0);
    }

public boolean doHurtTarget(Entity entity) {
        if(this.getAnimation() == NO_ANIMATION){
