@Override
    public void tick() {
        super.tick();
        BlockEntity te = this.entity.level().getBlockEntity(this.blockPos);
        if (te instanceof Container) {
            Container feeder = (Container) te;
            double distance = this.entity.distanceToSqr(this.blockPos.getX() + 0.5F, this.blockPos.getY() + 0.5F, this.blockPos.getZ() + 0.5F);
            entity.getNavigation().moveTo(this.blockPos.getX() + 0.5F, this.blockPos.getY() - 1, this.blockPos.getZ() + 0.5F, 1.0F);
            if (hasLineOfSightChest()) {
                entity.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(blockPos));
                if (distance <= acceptedDistance()) {
                    entity.getNavigation().stop();
                    chestLooter.startOpeningChest();
                    if (!hasOpenedChest) {
                        hasOpenedChest = true;
                        toggleChest(feeder, true);
                    }
                    if (hasOpenedChest && chestLooter.didOpeningChest()) {
                        toggleChest(feeder, false);
                        ItemStack stack = getFoodFromInventory(feeder, this.entity.level().random);
                        if (stack == ItemStack.EMPTY) {
                            this.stop();
                        } else {
                            ItemStack duplicate = stack.copy();
                            duplicate.setCount(1);
                            if (!this.entity.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && !this.entity.level().isClientSide) {
                                this.entity.spawnAtLocation(this.entity.getItemInHand(InteractionHand.MAIN_HAND), 0.0F);
                            }
                            this.entity.setItemInHand(InteractionHand.MAIN_HAND, duplicate);
                            stack.shrink(1);
                            chestLooter.afterSteal(blockPos);
                            this.stop();
                        }
                    }
                }
            }
        }
    }

public void stop() {
        super.stop();
        if (this.blockPos != null) {
            BlockEntity te = this.entity.level().getBlockEntity(this.blockPos);
            if (te instanceof Container) {
                toggleChest((Container) te, false);
            }
        }
        this.blockPos = BlockPos.ZERO;
        this.hasOpenedChest = false;
    }

public ItemStack getFoodFromInventory(Container inventory, RandomSource random) {
        List<ItemStack> items = new ArrayList<ItemStack>();
        for (int i = 0; i < inventory.getContainerSize(); i++) {
            ItemStack stack = inventory.getItem(i);
            if (!stack.isEmpty() && chestLooter.shouldLootItem(stack)) {
                items.add(stack);
            }
        }
        if (items.isEmpty()) {
            return ItemStack.EMPTY;
        } else if (items.size() == 1) {
            return items.get(0);
        } else {
            return items.get(random.nextInt(items.size() - 1));
        }
    }

public void toggleChest(Container te, boolean open) {
        if (te instanceof ChestBlockEntity) {
            ChestBlockEntity chest = (ChestBlockEntity) te;
            if (open) {
                this.entity.level().blockEvent(this.blockPos, chest.getBlockState().getBlock(), 1, 1);
            } else {
                this.entity.level().blockEvent(this.blockPos, chest.getBlockState().getBlock(), 1, 0);
            }
            this.entity.level().updateNeighborsAt(blockPos, chest.getBlockState().getBlock());
            this.entity.level().updateNeighborsAt(blockPos.below(), chest.getBlockState().getBlock());
        }
    }

public boolean isChestRaidable(LevelReader world, BlockPos pos) {
        if (world.getBlockState(pos).getBlock() instanceof BaseEntityBlock) {
            BlockEntity entity = world.getBlockEntity(pos);
            if (entity instanceof Container) {
                Container inventory = (Container) entity;
                try {
                    if (!inventory.isEmpty() && chestLooter.isLootable(inventory)) {
                        return true;
                    }
                } catch (Exception e) {
                    AlexsCaves.LOGGER.warn("Alex's Caves stopped a " + entity.getClass().getSimpleName() + " from causing a crash during access");
                    e.printStackTrace();
                }
            }
        }
        return false;
    }

default boolean isLootable(Container inventory) {
        for (int i = 0; i < inventory.getContainerSize(); i++) {
            if (shouldLootItem(inventory.getItem(i))) {
                return true;
            }
        }
        return false;
    }

public void tick() {
        super.tick();
        prevFishPitch = fishPitch;
        prevSummonedProgress = summonedProgress;
        boolean water = this.isInWaterOrBubble();
        if (water && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!water && !this.isLandNavigator) {
            switchNavigator(true);
        }
        float pitchTarget;
        if (isDeepOneSwimming()) {
            pitchTarget = (float) this.getDeltaMovement().y * getPitchScale();
            if (!level().isClientSide && this.getNavigation().isDone() && this.onGround()) {
                this.setDeepOneSwimming(false);
            }
        } else {
            pitchTarget = 0;
        }
        if (isSummoned()) {
            if (this.getSummonTime() > 0) {
                if (summonedProgress < 20.0F) {
                    if (summonedProgress == 0) {
                        if (!level().isClientSide) {
                            this.level().broadcastEntityEvent(this, (byte) 61);
                        }
                        this.playSound(ACSoundRegistry.MAGIC_CONCH_SUMMON.get());
                    }
                    summonedProgress++;
                }
            } else {
                if (summonedProgress > 0.0F) {
                    summonedProgress--;
                }
            }
            if (getSummonTime() > 0) {
                if (!level().isClientSide) {
                    setSummonTime(getSummonTime() - 1);
                }
                if (getSummonTime() == 0) {
                    if (!level().isClientSide) {
                        this.level().broadcastEntityEvent(this, (byte) 61);
                    }
                    this.playSound(ACSoundRegistry.MAGIC_CONCH_SUMMON.get());
                }
            } else {
                if (!level().isClientSide && this.summonedProgress <= 0) {
                    this.remove(RemovalReason.DISCARDED);
                }
            }
        }
        if (!isSummoned() && summonedProgress > 0.0F) {
            summonedProgress--;
        }
        if (hasSwimmingBoundingBox()) {
            if (!hasSwimmingSize) {
                hasSwimmingSize = true;
                refreshDimensions();
            }
        } else {
            if (hasSwimmingSize) {
                hasSwimmingSize = false;
                refreshDimensions();
            }
        }
        if (tradingLockedTime > 0) {
            tradingLockedTime--;
        }
        if (!level().isClientSide && this.getAnimation() == getTradingAnimation() && this.getMainHandItem().is(ACTagRegistry.DEEP_ONE_BARTERS)) {
            BlockPos altarPos = getLastAltarPos();
            if (altarPos != null) {
                Vec3 center = Vec3.atCenterOf(altarPos);
                if (this.getAnimationTick() > getTradingAnimation().getDuration() - 10) {
                    if (level().getBlockEntity(altarPos) instanceof AbyssalAltarBlockEntity altar && !spawnedLootItem) {
                        List<ItemStack> possibles = generateBarterLoot();
                        ItemStack stack = possibles.isEmpty() ? ItemStack.EMPTY : possibles.get(0);
                        if (altar.getItem(0).isEmpty()) {
                            altar.setItem(0, stack);
                            this.level().broadcastEntityEvent(this, (byte) 68);
                            altar.onEntityInteract(this, false);
                        } else {
                            Vec3 vec3 = center.add(0, 0.5F, 0);
                            ItemEntity itemEntity = new ItemEntity(level(), vec3.x, vec3.y, vec3.z, stack);
                            level().addFreshEntity(itemEntity);
                        }
                        double advancementRange = 20.0D;
                        for (Player player : level().getNearbyPlayers(TargetingConditions.forNonCombat().range(advancementRange), this, this.getBoundingBox().inflate(advancementRange))) {
                            if (player.distanceTo(this) < advancementRange) {
                                ACAdvancementTriggerRegistry.DEEP_ONE_TRADE.triggerForEntity(player);
                            }
                        }
                        spawnedLootItem = true;
                    }
                    restoreSwappedItem();
                }
                this.lookAt(EntityAnchorArgument.Anchor.EYES, center);
            }
        }
        if (spawnedLootItem && this.getAnimation() != getTradingAnimation()) {
            spawnedLootItem = false;
        }
        fishPitch = Mth.approachDegrees(fishPitch, Mth.clamp((float) pitchTarget, -1.4F, 1.4F) * -(float) (180F / (float) Math.PI), 5);
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

