public void handleEntityEvent(byte b) {
        if (b == 61) {
            this.level().addParticle(ACParticleRegistry.BIG_SPLASH.get(), this.getX(), this.getY() + 0.5F, this.getZ(), this.getBbWidth() + 0.2F, 3, 0);

        } else if (b == 68) {
            BlockPos pos = getLastAltarPos();
            if (pos != null && level().getBlockEntity(pos) instanceof AbyssalAltarBlockEntity altarBlockEntity) {
                altarBlockEntity.onEntityInteract(this, false);
            }
        } else if (b == 69) {
            BlockPos pos = getLastAltarPos();
            if (pos != null && level().getBlockEntity(pos) instanceof AbyssalAltarBlockEntity altarBlockEntity) {
                altarBlockEntity.onEntityInteract(this, true);
                altarBlockEntity.setItem(0, ItemStack.EMPTY);
            }
        } else {
            super.handleEntityEvent(b);
        }
    }

@Override
    public boolean canUse() {
        LivingEntity target = mob.getTarget();
        if ((target == null || !target.isAlive()) && mob.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
            if (executionCooldown-- > 0) {
                return false;
            } else {
                executionCooldown = 150 + mob.getRandom().nextInt(100);
                BlockPos pos = null;
                if (mob.getLastAltarPos() != null) {
                    if (mob.level().getBlockEntity(mob.getLastAltarPos()) instanceof AbyssalAltarBlockEntity altar) {
                        executionCooldown = 10;
                        if (altar.getItem(0).is(ACTagRegistry.DEEP_ONE_BARTERS)) {
                            pos = mob.getLastAltarPos();
                        }
                    } else {
                        mob.setLastAltarPos(null);
                    }
                }
                if (pos == null) {
                    List<BlockPos> list = getNearbyAltars(mob.blockPosition(), (ServerLevel) mob.level(), 64).sorted(Comparator.comparingDouble(mob.blockPosition()::distSqr)).toList();
                    if (!list.isEmpty()) {
                        pos = list.get(0);
                    }
                }
                if (pos != null) {
                    altarPos = pos;
                    mob.setLastAltarPos(altarPos);
                    return true;
                }
            }
        }
        return false;
    }

@Override
    public boolean canContinueToUse() {
        LivingEntity target = mob.getTarget();
        return altarPos != null && (hasPearls(mob.level(), altarPos, false) || mob.getAnimation() == mob.getTradingAnimation()) && (target == null || !target.isAlive());
    }

public void tick() {
        Vec3 center = Vec3.atCenterOf(altarPos);
        double distance = Vec3.atBottomCenterOf(altarPos).subtract(mob.position()).horizontalDistance();
        if (distance < 8) {
            mob.getLookControl().setLookAt(center.x, center.y, center.z, 10.0F, (float) this.mob.getMaxHeadXRot());
        }
        if (distance > 3) {
            mob.getNavigation().moveTo(altarPos.getX() + 0.5F, altarPos.getY(), altarPos.getZ() + 0.5F, 1);
        } else {
            mob.setLastAltarPos(altarPos);
            mob.setTradingLockedTime(50);
            mob.getNavigation().stop();
            if (mob.level().getBlockEntity(altarPos) instanceof AbyssalAltarBlockEntity altar) {
                if (altar.getItem(0).is(ACTagRegistry.DEEP_ONE_BARTERS)) {
                    if (altar.queueItemDrop(altar.getItem(0))) {
                        mob.level().broadcastEntityEvent(mob, (byte) 69);
                        altar.onEntityInteract(mob, true);
                        altar.setItem(0, ItemStack.EMPTY);
                    }
                }
            }
        }
    }

private static boolean hasPearls(Level world, BlockPos pos, boolean timed) {
        if (world.getBlockEntity(pos) instanceof AbyssalAltarBlockEntity altar) {
            if (timed && world.getGameTime() - altar.getLastInteractionTime() < 100) {
                return false;
            }
            return altar.getItem(0).is(ACTagRegistry.DEEP_ONE_BARTERS) && altar.getBlockState().getBlock() instanceof AbyssalAltarBlock && !altar.getBlockState().getValue(AbyssalAltarBlock.ACTIVE);
        }
        return false;
    }

private static Stream<BlockPos> getNearbyAltars(BlockPos blockpos, ServerLevel world, int range) {
        PoiManager pointofinterestmanager = world.getPoiManager();
        return pointofinterestmanager.findAll(poiTypeHolder -> poiTypeHolder.is(ACPOIRegistry.ABYSSAL_ALTAR.getKey()), blockpos2 -> hasPearls(world, blockpos2, true), blockpos, range, PoiManager.Occupancy.ANY);
    }

public static void tick(Level level, BlockPos pos, BlockState state, AbyssalAltarBlockEntity entity) {
        if (level.isClientSide) {
            ItemStack itemStack = entity.getItem(0);
            if (!itemStack.equals(entity.displayCopyStack, false) || entity.slideImpulse) {
                if (entity.slideProgress > 0.0F) {
                    entity.prevSlideProgress = entity.slideProgress;
                    entity.slideProgress--;
                } else {
                    entity.prevSlideProgress = entity.slideProgress;
                    entity.slideImpulse = false;
                    entity.displayCopyStack = itemStack.copy();
                }
            }
        }
        if (entity.popStack != null && !level.isClientSide) {
            if (entity.popDelay++ > 6) {
                ItemStack drop = entity.popStack.copy();
                Vec3 angleAdd = new Vec3(0, 0, 1).yRot(entity.itemAngle * ((float) Math.PI / 180F));
                Vec3 vec3 = Vec3.atCenterOf(entity.worldPosition).add(0, 0.5F, 0).add(angleAdd);
                ItemEntity itemEntity = new ItemEntity(level, vec3.x, vec3.y, vec3.z, drop);
                if (entity.lastInteracter != null) {
                    itemEntity.setThrower(entity.lastInteracter.getUUID());
                    boolean kill = true;
                    if (entity.lastInteracter instanceof Player player) {
                        boolean fullInv = !hasInventorySpaceFor(player.getInventory(), drop);
                        if (!player.addItem(drop.copy()) || player.getAbilities().instabuild && fullInv) {
                            kill = false;
                        }
                    } else if (entity.lastInteracter instanceof DeepOneBaseEntity deepOne) {
                        deepOne.swapItemsForAnimation(itemEntity.getItem());
                        deepOne.setItemInHand(InteractionHand.MAIN_HAND, itemEntity.getItem());
                        deepOne.setAnimation(deepOne.getTradingAnimation());
                        deepOne.playSound(deepOne.getAdmireSound());
                        if (entity.placingPlayer != null) {
                            deepOne.addReputation(entity.placingPlayer, 5);
                            entity.placingPlayer = null;
                        }
                        kill = true;
                    }
                    itemEntity.setItem(drop);
                    if (kill) {
                        entity.lastInteracter.onItemPickup(itemEntity);
                        entity.lastInteracter.take(itemEntity, drop.getCount());
                        itemEntity.discard();
                    }else{
                        level.addFreshEntity(itemEntity);
                        itemEntity.setDefaultPickUpDelay();
                    }
                }
                entity.popStack = null;
                entity.lastInteracter = null;
            }
        }
    }

public boolean queueItemDrop(ItemStack copy) {
        if (popStack != null) {
            return false;
        }
        popStack = copy;
        return true;
    }

public void onEntityInteract(LivingEntity entity, boolean flip) {
        displayCopyStack = this.getItem(0).copy();
        if (flip) {
            if (this.getBlockState().getValue(AbyssalAltarBlock.ACTIVE)) {
                level.setBlockAndUpdate(this.worldPosition, this.getBlockState().setValue(AbyssalAltarBlock.ACTIVE, false));
            }
        } else {
            if (entity instanceof DeepOneBaseEntity) {
                level.setBlockAndUpdate(this.worldPosition, this.getBlockState().setValue(AbyssalAltarBlock.ACTIVE, true));
            }
        }
        Vec3 vec3 = entity.position().subtract(Vec3.atCenterOf(this.worldPosition));
        itemAngle = Mth.wrapDegrees((float) (Mth.atan2(vec3.x, vec3.z) * (double) (180F / (float) Math.PI)));
        lastInteracter = entity;
        popDelay = 0;
        resetSlideAnimation();
        if(!level.isClientSide){
            BlockPos blockPos = this.getBlockPos();
            AlexsCaves.sendMSGToAll(new WorldEventMessage(6, blockPos.getX(), blockPos.getY(), blockPos.getZ()));
        }
        if (entity instanceof Player) {
            placingPlayer = entity.getUUID();
        } else {
            lastInteractionTime = entity.level().getGameTime();
        }
    }

